   312→    .file-info { flex: 1; min-width: 100px; }
   313→    .file-info strong { display: block; font-size: 0.88rem; word-break: break-all; }
   314→    .file-info span { font-size: 0.75rem; color: var(--muted); }
   315→
   316→    /* ── Link list ── */
   317→    .link-list { display: flex; flex-direction: column; gap: 6px; }
   318→    .link-row {
   319→      background: var(--surface);
   320→      border: 1px solid var(--border);
   321→      border-radius: 8px;
   322→      padding: 10px 14px;
   323→      display: flex;
   324→      align-items: center;
   325→      gap: 10px;
   326→      flex-wrap: wrap;
   327→    }
   328→    .link-text { flex: 1; font-size: 0.85rem; font-weight: 600; min-width: 80px; }
   329→    .link-url  { flex: 2; font-size: 0.75rem; color: var(--muted); word-break: break-all; }
   330→
   331→    /* ── Product blocks ── */
   332→    .product-grid {
   333→      display: grid;
