   342→    }
   343→    .product-card img { width: 100%; height: 140px; object-fit: cover; }
   344→    .product-card .product-body { padding: 14px; }
   345→    .product-card .product-title { font-weight: 600; font-size: 0.92rem; margin-bottom: 8px; }
   346→    .product-card .price-tags { display: flex; gap: 6px; flex-wrap: wrap; margin-bottom: 10px; }
   347→    .price-tag {
   348→      background: #312e81;
   349→      color: #a5b4fc;
