   364→
   365→    /* ── Heading list ── */
   366→    .heading-list { display: flex; flex-direction: column; gap: 6px; }
   367→    .heading-row {
   368→      display: flex;
   369→      align-items: baseline;
   370→      gap: 10px;
   371→      padding: 8px 12px;
   372→      background: var(--surface);
