   411→    .json-key   { color: #7dcfff; }
   412→    .json-str   { color: #9ece6a; }
   413→    .json-num   { color: #ff9e64; }
   414→    .json-bool  { color: #bb9af7; }
   415→    .json-null  { color: #565f89; }
   416→
   417→    /* ── Crawl results ── */
   418→    .crawl-results { display: flex; flex-direction: column; gap: 12px; }
   419→    .crawl-page {
   420→      background: var(--surface);
   421→      border: 1px solid var(--border);
