   427→    .crawl-page:hover { border-color: var(--accent2); }
   428→    .crawl-page strong { display: block; font-size: 0.9rem; margin-bottom: 4px; }
   429→    .crawl-page .crawl-url { font-size: 0.75rem; color: var(--muted); word-break: break-all; }
   430→    .crawl-chips { display: flex; gap: 6px; flex-wrap: wrap; margin-top: 8px; }
   431→    .crawl-chip {
   432→      font-size: 0.7rem;
   433→      background: var(--surface2);
   434→      border: 1px solid var(--border);
   435→      border-radius: 4px;
