   439→
   440→    /* ── Scrollbar ── */
   441→    ::-webkit-scrollbar { width: 6px; height: 6px; }
   442→    ::-webkit-scrollbar-track { background: transparent; }
   443→    ::-webkit-scrollbar-thumb { background: var(--border); border-radius: 3px; }
   444→  </style>
   445→</head>
   446→<body>
   447→<div class="app">
   448→
   449→  <!-- Header -->
   450→  <header>
   451→    <h1>Scraper <span>POC</span></h1>
   452→    <p>Enter any URL to extract images, fonts, PDFs, links, and product blocks — all in one shot.</p>
   453→  </header>
   454→
   455→  <!-- Input card -->
   456→  <div class="input-card">
   457→    <div class="input-row">
   458→      <input
   459→        type="url"
   460→        id="url-input"
   461→        placeholder="https://example.com/products/something"
   462→        autocomplete="off"
   463→      />
   464→      <button class="btn" id="scrape-btn" onclick="doScrape()">Scrape</button>
   465→      <button class="btn btn-outline" id="crawl-btn" onclick="doCrawl()">Crawl</button>
   466→    </div>
   467→    <div class="options-row">
   468→      <label title="Delegate rendering to ScraperAPI (requires SCRAPERAPI_KEY env var)">
   469→        <input type="checkbox" id="use-api" />
   470→        Use ScraperAPI
   471→      </label>
   472→      <label title="How many pages to follow when crawling">
   473→        Crawl depth
   474→        <input type="number" id="max-pages" value="5" min="1" max="20" />
   475→      </label>
   476→      <label title="Regex filter for links to follow during crawl">
   477→        Path filter
   478→        <input
   479→          type="text"
   480→          id="path-filter"
   481→          value=".*"
   482→          style="width:120px;background:var(--surface2);border:1px solid var(--border);border-radius:6px;padding:4px 8px;color:var(--text);font-size:0.83rem;"
   483→        />
   484→      </label>
   485→    </div>
   486→    <div id="status">
   487→      <span class="spinner" id="spinner"></span>
   488→      <span id="status-text">Ready — enter a URL above and press Scrape.</span>
   489→    </div>
   490→  </div>
   491→
   492→  <!-- Page meta -->
   493→  <div id="page-meta"></div>
   494→
   495→  <!-- Summary chips -->
   496→  <div id="summary"></div>
   497→
   498→  <!-- Tabs -->
   499→  <div id="results" style="display:none;">
   500→    <div class="tabs">
   501→      <button class="tab-btn active" onclick="switchTab('images', this)">Images</button>
   502→      <button class="tab-btn" onclick="switchTab('fonts', this)">Fonts</button>
   503→      <button class="tab-btn" onclick="switchTab('files', this)">PDFs &amp; Files</button>
   504→      <button class="tab-btn" onclick="switchTab('links', this)">Links</button>
   505→      <button class="tab-btn" onclick="switchTab('products', this)">Products</button>
   506→      <button class="tab-btn" onclick="switchTab('headings', this)">Headings</button>
   507→      <button class="tab-btn" onclick="switchTab('json', this)">JSON</button>
   508→    </div>
   509→
   510→    <!-- Images -->
   511→    <div id="tab-images" class="tab-panel active">
   512→      <div class="section-header">
   513→        <span class="section-title">Images</span>
   514→        <span class="count-badge" id="img-count">0</span>
   515→      </div>
   516→      <div id="image-grid" class="image-grid"></div>
   517→    </div>
   518→
   519→    <!-- Fonts -->
   520→    <div id="tab-fonts" class="tab-panel">
   521→      <div class="section-header">
   522→        <span class="section-title">Fonts</span>
   523→        <span class="count-badge" id="font-count">0</span>
   524→      </div>
   525→      <div id="font-list" class="font-list"></div>
   526→    </div>
   527→
   528→    <!-- Files -->
   529→    <div id="tab-files" class="tab-panel">
   530→      <div class="section-header">
   531→        <span class="section-title">PDFs &amp; Files</span>
   532→        <span class="count-badge" id="file-count">0</span>
   533→      </div>
   534→      <div id="file-list" class="file-list"></div>
   535→    </div>
   536→
   537→    <!-- Links -->
   538→    <div id="tab-links" class="tab-panel">
   539→      <div class="section-header">
   540→        <span class="section-title">Internal Links</span>
   541→        <span class="count-badge" id="link-count">0</span>
   542→      </div>
   543→      <div id="link-list" class="link-list"></div>
   544→
   545→      <div class="section-header" style="margin-top:24px;">
   546→        <span class="section-title">External Links</span>
   547→        <span class="count-badge" id="ext-link-count">0</span>
   548→      </div>
   549→      <div id="ext-link-list" class="link-list"></div>
   550→    </div>
   551→
   552→    <!-- Products -->
   553→    <div id="tab-products" class="tab-panel">
   554→      <div class="section-header">
   555→        <span class="section-title">Product / Pricing Blocks</span>
   556→        <span class="count-badge" id="product-count">0</span>
   557→      </div>
   558→      <div id="product-grid" class="product-grid"></div>
   559→    </div>
   560→
   561→    <!-- Headings -->
   562→    <div id="tab-headings" class="tab-panel">
   563→      <div class="section-header">
   564→        <span class="section-title">Headings</span>
   565→        <span class="count-badge" id="heading-count">0</span>
   566→      </div>
   567→      <div id="heading-list" class="heading-list"></div>
   568→    </div>
   569→
   570→    <!-- JSON -->
   571→    <div id="tab-json" class="tab-panel">
   572→      <div class="section-header">
   573→        <span class="section-title">Raw JSON Output</span>
   574→        <button class="btn btn-outline btn-sm" onclick="downloadJson()">Download JSON</button>
   575→      </div>
   576→      <div id="json-output"></div>
   577→    </div>
   578→  </div>
   579→
   580→  <!-- Crawl results (separate from single-page tabs) -->
   581→  <div id="crawl-results-container" style="display:none;margin-top:12px;">
   582→    <div class="section-header">
   583→      <span class="section-title">Crawl Results</span>
   584→      <button class="btn btn-outline btn-sm" onclick="downloadCrawlJson()">Download All JSON</button>
   585→    </div>
   586→    <div id="crawl-list" class="crawl-results"></div>
   587→  </div>
   588→
   589→</div>
   590→
   591→<script>
   592→// ── State ──────────────────────────────────────────────────────────────────
   593→let lastResult = null;
   594→let lastCrawlResult = null;
   595→
   596→// ── Tab switching ──────────────────────────────────────────────────────────
   597→function switchTab(name, btn) {
   598→  document.querySelectorAll('.tab-panel').forEach(p => p.classList.remove('active'));
   599→  document.querySelectorAll('.tab-btn').forEach(b => b.classList.remove('active'));
   600→  document.getElementById('tab-' + name).classList.add('active');
   601→  btn.classList.add('active');
   602→}
   603→
   604→// ── Status helpers ─────────────────────────────────────────────────────────
   605→function setStatus(msg, type = '') {
   606→  const el = document.getElementById('status');
   607→  const txt = document.getElementById('status-text');
   608→  el.className = type;
   609→  txt.textContent = msg;
   610→}
   611→
   612→function setLoading(msg) { setStatus(msg, 'loading'); }
   613→function setError(msg)   { setStatus('Error: ' + msg, 'error'); }
   614→function setOk(msg)      { setStatus(msg, 'ok'); }
   615→
   616→function setBusy(busy) {
   617→  document.getElementById('scrape-btn').disabled = busy;
   618→  document.getElementById('crawl-btn').disabled  = busy;
   619→}
   620→
   621→// ── Single-page scrape ─────────────────────────────────────────────────────
   622→async function doScrape() {
   623→  const url = document.getElementById('url-input').value.trim();
   624→  if (!url) { setError('Please enter a URL.'); return; }
   625→
   626→  const useApi = document.getElementById('use-api').checked;
   627→
   628→  setLoading('Scraping…');
   629→  setBusy(true);
   630→  clearResults();
   631→
   632→  try {
   633→    const res = await fetch('/api/scrape', {
   634→      method: 'POST',
   635→      headers: { 'Content-Type': 'application/json' },
   636→      body: JSON.stringify({ url, useApi }),
   637→    });
   638→    const data = await res.json();
   639→    if (!res.ok) throw new Error(data.error + (data.tip ? '\n\n💡 ' + data.tip : ''));
   640→
   641→    lastResult = data;
   642→    renderResult(data);
   643→    setOk(`Done — ${data.summary.images} images, ${data.summary.fonts} fonts, ${data.summary.files} files found.`);
   644→  } catch (e) {
   645→    setError(e.message);
   646→  } finally {
   647→    setBusy(false);
   648→  }
   649→}
   650→
   651→// ── Multi-page crawl ───────────────────────────────────────────────────────
   652→async function doCrawl() {
   653→  const url        = document.getElementById('url-input').value.trim();
   654→  const maxPages   = parseInt(document.getElementById('max-pages').value) || 5;
   655→  const pathFilter = document.getElementById('path-filter').value || '.*';
   656→  const useApi     = document.getElementById('use-api').checked;
   657→
   658→  if (!url) { setError('Please enter a URL.'); return; }
   659→
   660→  setLoading(`Crawling up to ${maxPages} pages…`);
   661→  setBusy(true);
   662→  clearResults();
   663→
   664→  try {
   665→    const res = await fetch('/api/crawl', {
   666→      method: 'POST',
   667→      headers: { 'Content-Type': 'application/json' },
   668→      body: JSON.stringify({ url, pathFilter, maxPages, useApi }),
   669→    });
   670→    const data = await res.json();
   671→    if (!res.ok) throw new Error(data.error);
   672→
   673→    lastCrawlResult = data;
   674→    renderCrawlResults(data);
   675→    setOk(`Crawled ${data.pages} pages.`);
   676→  } catch (e) {
   677→    setError(e.message);
   678→  } finally {
   679→    setBusy(false);
   680→  }
   681→}
   682→
   683→// Enter key submits scrape
   684→document.getElementById('url-input').addEventListener('keydown', e => {
   685→  if (e.key === 'Enter') doScrape();
   686→});
   687→
   688→// ── Clear ──────────────────────────────────────────────────────────────────
   689→function clearResults() {
   690→  document.getElementById('results').style.display = 'none';
   691→  document.getElementById('crawl-results-container').style.display = 'none';
   692→  document.getElementById('summary').innerHTML = '';
   693→  document.getElementById('page-meta').style.display = 'none';
   694→  lastResult = null;
   695→  lastCrawlResult = null;
   696→}
   697→
   698→// ── Render single result ───────────────────────────────────────────────────
   699→function renderResult(data) {
   700→  document.getElementById('crawl-results-container').style.display = 'none';
   701→
   702→  // Page meta
   703→  const meta = document.getElementById('page-meta');
   704→  meta.style.display = 'block';
   705→  meta.innerHTML = `
   706→    <strong>${esc(data.meta.title || '(no title)')}</strong>
   707→    <span>${esc(data.meta.description || '')}</span>
   708→    <span style="display:block;margin-top:4px;color:var(--muted);font-size:0.75rem;">
   709→      ${esc(data.meta.url)} · mode: ${data.meta.mode} · scraped ${new Date(data.meta.scrapedAt).toLocaleTimeString()}
   710→    </span>
   711→  `;
   712→
   713→  // Summary chips
   714→  const s = data.summary;
   715→  document.getElementById('summary').innerHTML = [
   716→    chip('Images', s.images),
   717→    chip('Fonts', s.fonts),
   718→    chip('Files', s.files),
   719→    chip('Internal links', s.internalLinks),
   720→    chip('External links', s.externalLinks),
   721→    chip('Products', s.productBlocks),
   722→    chip('Headings', s.headings),
   723→  ].join('');
   724→
   725→  // Show results container, switch to first tab
   726→  document.getElementById('results').style.display = 'block';
   727→  switchTab('images', document.querySelector('.tab-btn'));
   728→
   729→  // Render each section
   730→  renderImages(data.images);
   731→  renderFonts(data.fonts);
   732→  renderFiles(data.files);
   733→  renderLinks(data.links);
   734→  renderProducts(data.productBlocks);
   735→  renderHeadings(data.headings);
   736→  renderJson(data);
   737→}
   738→
   739→// ── Chip helper ───────────────────────────────────────────────────────────
   740→function chip(label, count) {
   741→  return `<div class="chip">${esc(label)} <span class="chip-count">${count}</span></div>`;
   742→}
   743→
   744→// ── Images ────────────────────────────────────────────────────────────────
   745→function renderImages(images) {
   746→  document.getElementById('img-count').textContent = images.length;
   747→  const el = document.getElementById('image-grid');
   748→  if (!images.length) { el.innerHTML = empty('No images found'); return; }
   749→
   750→  el.innerHTML = images.map(img => `
   751→    <div class="image-card">
   752→      <img
   753→        class="thumb"
   754→        src="${esc(img.src)}"
   755→        alt="${esc(img.alt)}"
   756→        onerror="this.style.display='none';this.nextElementSibling.style.display='flex'"
   757→        loading="lazy"
   758→      />
   759→      <div class="thumb-error" style="display:none">🖼</div>
   760→      <div class="card-body">
   761→        <div class="card-label" title="${esc(img.src)}">${esc(fileName(img.src))}</div>
   762→        ${img.alt ? `<div class="card-label">${esc(img.alt.slice(0,40))}</div>` : ''}
   763→        <div class="card-actions">
   764→          <a class="btn btn-outline btn-sm" href="/api/download?url=${enc(img.src)}&filename=${enc(fileName(img.src))}" download>↓ Download</a>
   765→        </div>
   766→      </div>
   767→    </div>
   768→  `).join('');
   769→}
   770→
   771→// ── Fonts ─────────────────────────────────────────────────────────────────
   772→function renderFonts(fonts) {
   773→  document.getElementById('font-count').textContent = fonts.length;
   774→  const el = document.getElementById('font-list');
   775→  if (!fonts.length) {
   776→    el.innerHTML = empty('No @font-face fonts found on this page');
   777→    return;
   778→  }
   779→
   780→  el.innerHTML = fonts.map(f => `
   781→    <div class="font-card">
   782→      <div class="font-preview" style="font-family:'${esc(f.family)}',sans-serif;">
   783→        Aa Bb Cc
   784→      </div>
   785→      <div class="font-meta">
   786→        <strong>${esc(f.family)}</strong>
   787→        <span>weight ${esc(f.weight)} · ${esc(f.style)}</span>
   788→      </div>
   789→      <div style="display:flex;gap:6px;flex-wrap:wrap;align-items:center;">
   790→        ${f.sources.map(s => `<span class="font-badge">${s.format}</span>`).join('')}
   791→      </div>
   792→      <div style="margin-left:auto;">
   793→        <a class="btn btn-sm" href="/api/download?url=${enc(f.downloadUrl)}&filename=${enc(f.family + '-' + f.weight + '.' + f.format)}" download>
   794→          ↓ Download ${f.format.toUpperCase()}
   795→        </a>
   796→      </div>
   797→    </div>
   798→  `).join('');
   799→}
   800→
   801→// ── Files ─────────────────────────────────────────────────────────────────
   802→function renderFiles(files) {
   803→  document.getElementById('file-count').textContent = files.length;
   804→  const el = document.getElementById('file-list');
   805→  if (!files.length) { el.innerHTML = empty('No downloadable files found'); return; }
   806→
   807→  el.innerHTML = files.map(f => `
   808→    <div class="file-row">
   809→      <div class="file-icon ${fileIconClass(f.ext)}">${esc(f.type)}</div>
   810→      <div class="file-info">
   811→        <strong>${esc(f.text.slice(0,80))}</strong>
