   943→function esc(str) {
   944→  if (str == null) return '';
   945→  return String(str)
   946→    .replace(/&/g, '&amp;')
   947→    .replace(/</g, '&lt;')
   948→    .replace(/>/g, '&gt;')
   949→    .replace(/"/g, '&quot;');
