   975→
   976→function triggerDownload(content, filename, type) {
   977→  const blob = new Blob([content], { type });
   978→  const url  = URL.createObjectURL(blob);
   979→  const a    = document.createElement('a');
   980→  a.href = url;
   981→  a.download = filename;
   982→  a.click();
   983→  URL.revokeObjectURL(url);
   984→}
   985→
   986→function syntaxHighlight(json) {
   987→  return json.replace(
   988→    /("(\\u[a-zA-Z0-9]{4}|\\[^u]|[^\\"])*"(\s*:)?|\b(true|false|null)\b|-?\d+(?:\.\d*)?(?:[eE][+\-]?\d+)?)/g,
   989→    match => {
   990→      let cls = 'json-num';
   991→      if (/^"/.test(match)) cls = /:$/.test(match) ? 'json-key' : 'json-str';
   992→      else if (/true|false/.test(match)) cls = 'json-bool';
   993→      else if (/null/.test(match)) cls = 'json-null';
   994→      return `<span class="${cls}">${match}</span>`;
   995→    }
   996→  );
