   746→<script>
   747→let lastResult = null;
   748→let lastCrawlResult = null;
   749→
   750→// ── Tabs ───────────────────────────────────────────────────────────────────
   751→function switchTab(name, btn) {
   752→  document.querySelectorAll('.tab-panel').forEach(p => p.classList.remove('active'));
   753→  document.querySelectorAll('.tab-btn').forEach(b => b.classList.remove('active'));
   754→  document.getElementById('tab-' + name).classList.add('active');
   755→  if (btn) btn.classList.add('active');
   756→}
   757→function switchTabByName(name) {
   758→  switchTab(name, document.getElementById('tab-btn-' + name));
   759→}
   760→
   761→// ── Status ─────────────────────────────────────────────────────────────────
   762→function setStatus(msg, type = '') {
   763→  document.getElementById('status-text').textContent = msg;
   764→  document.getElementById('status-dot').className = 'status-dot ' + type;
   765→  document.getElementById('spinner').style.display = type === 'loading' ? 'inline-block' : 'none';
   766→}
   767→function setLoading(msg) { setStatus(msg, 'loading'); }
   768→function setError(msg)   { setStatus('Error: ' + msg, 'error'); }
   769→function setOk(msg)      { setStatus(msg, 'ok'); }
   770→
   771→function setBusy(busy) {
   772→  document.getElementById('scrape-btn').disabled = busy;
   773→  document.getElementById('crawl-btn').disabled  = busy;
   774→}
   775→
   776→// ── Scrape ─────────────────────────────────────────────────────────────────
   777→async function doScrape() {
   778→  const url    = document.getElementById('url-input').value.trim();
   779→  const useApi = document.getElementById('use-api').checked;
   780→  if (!url) { setError('Please enter a URL.'); return; }
   781→  setLoading('Scraping…');
   782→  setBusy(true);
   783→  clearResults();
   784→  try {
   785→    const res  = await fetch('/api/scrape', {
   786→      method: 'POST',
   787→      headers: { 'Content-Type': 'application/json' },
   788→      body: JSON.stringify({ url, useApi }),
   789→    });
   790→    const data = await res.json();
   791→    if (!res.ok) throw new Error(data.error + (data.tip ? ' — ' + data.tip : ''));
   792→    lastResult = data;
   793→    renderResult(data);
   794→    setOk(`${data.summary.images} images · ${data.summary.fonts} fonts · ${data.summary.files} files`);
   795→  } catch (e) {
   796→    setError(e.message);
   797→  } finally {
   798→    setBusy(false);
   799→  }
   800→}
   801→
   802→// ── Crawl ──────────────────────────────────────────────────────────────────
   803→async function doCrawl() {
   804→  const url        = document.getElementById('url-input').value.trim();
   805→  const maxPages   = parseInt(document.getElementById('max-pages').value) || 5;
   806→  const pathFilter = document.getElementById('path-filter').value || '.*';
   807→  const useApi     = document.getElementById('use-api').checked;
   808→  if (!url) { setError('Please enter a URL.'); return; }
   809→  setLoading(`Crawling up to ${maxPages} pages…`);
   810→  setBusy(true);
   811→  clearResults();
   812→  try {
   813→    const res  = await fetch('/api/crawl', {
   814→      method: 'POST',
   815→      headers: { 'Content-Type': 'application/json' },
   816→      body: JSON.stringify({ url, pathFilter, maxPages, useApi }),
   817→    });
   818→    const data = await res.json();
   819→    if (!res.ok) throw new Error(data.error);
   820→    lastCrawlResult = data;
   821→    renderCrawlResults(data);
   822→    setOk(`Crawled ${data.pages} pages`);
   823→  } catch (e) {
   824→    setError(e.message);
   825→  } finally {
   826→    setBusy(false);
   827→  }
   828→}
   829→
   830→document.getElementById('url-input').addEventListener('keydown', e => {
   831→  if (e.key === 'Enter') doScrape();
   832→});
