   995→}
   996→function downloadJson() {
   997→  if (!lastResult) return;
   998→  triggerDownload(JSON.stringify(lastResult, null, 2), 'scraper-result.json', 'application/json');
   999→}
  1000→
  1001→// ── Crawl results ──────────────────────────────────────────────────────────
  1002→function renderCrawlResults(data) {
  1003→  document.getElementById('results').style.display = 'none';
  1004→  document.getElementById('summary').style.display = 'none';
  1005→  document.getElementById('crawl-results-container').style.display = 'block';
  1006→  document.getElementById('crawl-list').innerHTML = data.results.map((r, i) => {
  1007→    if (r.error) return `
  1008→      <div class="crawl-card">
  1009→        <div class="crawl-page-title" style="color:var(--red)">Error</div>
  1010→        <div class="crawl-page-url">${esc(r.url)}</div>
  1011→        <div style="font-size:12px;color:var(--muted)">${esc(r.error)}</div>
  1012→      </div>`;
  1013→    const s = r.summary;
  1014→    return `
  1015→      <div class="crawl-card" onclick="openCrawlPage(${i})">
  1016→        <div class="crawl-page-title">${esc(r.meta.title || '(no title)')}</div>
  1017→        <div class="crawl-page-url">${esc(r.meta.url)}</div>
  1018→        <div class="crawl-tags">
  1019→          <span class="crawl-tag">${s.images} images</span>
  1020→          <span class="crawl-tag">${s.fonts} fonts</span>
  1021→          <span class="crawl-tag">${s.files} files</span>
  1022→          <span class="crawl-tag">${s.internalLinks} links</span>
  1023→          <span class="crawl-tag">${s.productBlocks} products</span>
  1024→        </div>
  1025→      </div>`;
  1026→  }).join('');
  1027→}
  1028→
  1029→function openCrawlPage(i) {
  1030→  if (!lastCrawlResult) return;
  1031→  const page = lastCrawlResult.results[i];
  1032→  lastResult = page;
  1033→  document.getElementById('crawl-results-container').style.display = 'none';
  1034→  renderResult(page);
  1035→  setOk('Showing: ' + page.meta.url);
  1036→}
  1037→function downloadCrawlJson() {
  1038→  if (!lastCrawlResult) return;
  1039→  triggerDownload(JSON.stringify(lastCrawlResult, null, 2), 'crawl-results.json', 'application/json');
  1040→}
  1041→
  1042→// ── Utils ──────────────────────────────────────────────────────────────────
  1043→function esc(s) {
  1044→  if (s == null) return '';
  1045→  return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
  1046→}
  1047→function enc(s) { return encodeURIComponent(s || ''); }
  1048→function fileName(url) {
  1049→  try { return decodeURIComponent(new URL(url).pathname.split('/').pop()) || url; }
  1050→  catch { return url; }
  1051→}
  1052→function fileIconClass(ext) {
  1053→  if (ext === 'pdf') return 'pdf';
  1054→  if (['zip','gz','tar','rar','7z'].includes(ext)) return 'zip';
  1055→  if (['doc','docx'].includes(ext)) return 'doc';
  1056→  if (['xls','xlsx','csv'].includes(ext)) return 'xlsx';
  1057→  return 'other';
  1058→}
  1059→function empty(msg) {
  1060→  return `<div class="empty"><div class="empty-dash">—</div><div class="empty-msg">${esc(msg)}</div></div>`;
  1061→}
  1062→function triggerDownload(content, filename, type) {
  1063→  const blob = new Blob([content], { type });
  1064→  const a = Object.assign(document.createElement('a'), { href: URL.createObjectURL(blob), download: filename });
  1065→  a.click();
  1066→  URL.revokeObjectURL(a.href);
  1067→}
  1068→function syntaxHighlight(json) {
  1069→  return json.replace(
  1070→    /("(\\u[a-zA-Z0-9]{4}|\\[^u]|[^\\"])*"(\s*:)?|\b(true|false|null)\b|-?\d+(?:\.\d*)?(?:[eE][+\-]?\d+)?)/g,
  1071→    m => {
  1072→      let c = 'json-num';
  1073→      if (/^"/.test(m)) c = /:$/.test(m) ? 'json-key' : 'json-str';
  1074→      else if (/true|false/.test(m)) c = 'json-bool';
  1075→      else if (/null/.test(m)) c = 'json-null';
  1076→      return `<span class="${c}">${m}</span>`;
  1077→    }
  1078→  );
  1079→}
  1080→</script>
  1081→</body>
  1082→</html>
  1083→

