   382→        /pdf/i.test(href + text + label) ? "pdf" :
   383→        /doc/i.test(href + text + label) ? "docx" :
   384→        /xls/i.test(href + text + label) ? "xlsx" : "";
   385→      push(href, text || label || title, guessedExt);
   386→    }
   387→  });
   388→
   389→  // 3. <iframe src>, <embed src>, <object data> — often used for inline PDFs
   390→  $("iframe[src], embed[src], object[data]").each((_, el) => {
   391→    const src = $(el).attr("src") || $(el).attr("data");
   392→    if (!src) return;
   393→    const ext = getExtension(src);
   394→    if (ext === "pdf" || DOWNLOADABLE_EXTENSIONS.has(ext)) {
   395→      const title = $(el).attr("title") || $(el).attr("name") || "";
   396→      push(src, title, ext || "pdf");
   397→    }
   398→  });
   399→
   400→  // 4. Inline <script> / data attributes — some React/Next sites embed file
   401→  //    URLs as JSON in data-* props (e.g. data-file-url, data-pdf-url)
   402→  $("[data-pdf-url], [data-file-url], [data-download-url], [data-href]").each((_, el) => {
   403→    const url =
   404→      $(el).attr("data-pdf-url") ||
   405→      $(el).attr("data-file-url") ||
   406→      $(el).attr("data-download-url") ||
   407→      $(el).attr("data-href");
   408→    if (url) {
   409→      const ext = getExtension(url);
   410→      push(url, $(el).text().trim(), ext || "pdf");
   411→    }
   412→  });
   413→
   414→  return dedupeBy(files, "url");
   415→}
   416→
   417→function fileName(url) {
   418→  try {
   419→    return decodeURIComponent(new URL(url).pathname.split("/").pop()) || url;
   420→  } catch {
   421→    return url;
   422→  }
   423→}
   424→
   425→// ---------------------------------------------------------------------------
   426→// Link extraction
   427→// ---------------------------------------------------------------------------
   428→
   429→function extractLinks($, baseUrl) {
   430→  const base = new URL(baseUrl);
   431→  const internal = [];
   432→  const external = [];
   433→
   434→  $("a[href]").each((_, el) => {
   435→    const href = $(el).attr("href");
   436→    if (!href || href.startsWith("mailto:") || href.startsWith("tel:") || href === "#")
   437→      return;
   438→
   439→    const abs = safeAbsolute(href, baseUrl);
   440→    if (!abs) return;
   441→
   442→    const parsed = new URL(abs);
   443→    const text = $(el).text().trim().replace(/\s+/g, " ").slice(0, 80);
   444→    const link = { href: abs.split("#")[0], text };
   445→
   446→    if (parsed.hostname === base.hostname) internal.push(link);
   447→    else external.push(link);
   448→  });
   449→
   450→  return {
   451→    internal: dedupeBy(internal, "href"),
   452→    external: dedupeBy(external, "href"),
   453→  };
   454→}
   455→
   456→// ---------------------------------------------------------------------------
   457→// Headings extraction
   458→// ---------------------------------------------------------------------------
   459→
   460→function extractHeadings($) {
   461→  const headings = [];
   462→  ["h1", "h2", "h3", "h4"].forEach((tag) => {
   463→    $(tag).each((_, el) => {
   464→      const text = $(el).text().trim().replace(/\s+/g, " ");
   465→      if (text) headings.push({ level: tag, text });
   466→    });
   467→  });
   468→  return headings;
   469→}
   470→
   471→// ---------------------------------------------------------------------------
   472→// Product / pricing block extraction
   473→// ---------------------------------------------------------------------------
   474→
   475→function extractProductBlocks($, baseUrl) {
   476→  const blocks = [];
   477→  const priceRe = /(?:AU\$|USD?\$|\$|€|£|¥)\s?\d[\d,]*(?:\.\d{2})?/gi;
   478→
   479→  // Check sections, articles, divs with class hints
   480→  const selectors = [
   481→    "section",
   482→    "article",
   483→    '[class*="product"]',
   484→    '[class*="card"]',
   485→    '[class*="price"]',
   486→    '[class*="item"]',
   487→  ];
   488→
   489→  const seen = new Set();
   490→
   491→  selectors.forEach((sel) => {
   492→    $(sel).each((_, el) => {
   493→      const text = $(el).text().trim().replace(/\s+/g, " ");
   494→      if (!text || seen.has(text.slice(0, 80))) return;
   495→
   496→      const priceMatches = text.match(priceRe);
   497→      if (!priceMatches) return;
   498→
   499→      seen.add(text.slice(0, 80));
   500→
   501→      // Grab any image inside the block
   502→      const imgEl = $(el).find("img[src]").first();
   503→      const imgSrc = imgEl.length
   504→        ? safeAbsolute(imgEl.attr("src"), baseUrl)
   505→        : null;
   506→
   507→      // Grab heading inside block
   508→      const heading = $(el).find("h1,h2,h3,h4,h5").first().text().trim();
   509→
   510→      blocks.push({
   511→        heading: heading || "",
   512→        prices: [...new Set(priceMatches)],
   513→        image: imgSrc,
   514→        snippet: text.slice(0, 400),
   515→      });
   516→    });
   517→  });
   518→
   519→  return blocks.slice(0, 30); // cap for demo
   520→}
   521→
   522→// ---------------------------------------------------------------------------
   523→// CSS background-image sweep across all stylesheets
   524→// ---------------------------------------------------------------------------
   525→
   526→async function extractCssBgImages($, baseUrl) {
   527→  const images = [];
   528→  const cssJobs = [];
   529→
   530→  $('link[rel~="stylesheet"][href]').each((_, el) => {
   531→    const href = $(el).attr("href");
   532→    const abs = safeAbsolute(href, baseUrl);
   533→    if (abs) cssJobs.push(abs);
   534→  });
   535→
   536→  $("style").each((_, el) => {
   537→    cssJobs.push({ inline: true, css: $(el).text() });
   538→  });
   539→
   540→  const resolved = await Promise.all(
   541→    cssJobs.slice(0, 6).map(async (job) => {
   542→      if (job?.inline) return { css: job.css, base: baseUrl };
   543→      const { css, finalUrl } = await fetchCss(job);
   544→      return { css, base: finalUrl };
   545→    })
   546→  );
   547→
   548→  for (const { css, base } of resolved) {
   549→    extractBgImages(css, base).forEach((url) =>
   550→      images.push({ src: url, alt: "", source: "css-background" })
   551→    );
   552→  }
   553→
   554→  return images;
   555→}
   556→
   557→// ---------------------------------------------------------------------------
   558→// Main entry point
   559→// ---------------------------------------------------------------------------
   560→
   561→/**
   562→ * Scrape a URL and return a structured result object.
   563→ *
   564→ * @param {string} url       - Target URL
   565→ * @param {boolean} useApi   - true = use ScraperAPI, false = direct fetch
   566→ * @returns {Promise<object>}
   567→ */
   568→export async function scrapeUrl(url, useApi = false) {
   569→  const html = useApi ? await fetchViaScraperApi(url) : await fetchDirect(url);
   570→
   571→  const $ = cheerio.load(html);
   572→  const title = $("title").text().trim().replace(/\s+/g, " ");
   573→  const description =
   574→    $('meta[name="description"]').attr("content") ||
   575→    $('meta[property="og:description"]').attr("content") ||
   576→    "";
   577→
   578→  // Run extractions (fonts + CSS bg images involve async network calls)
   579→  const [fonts, cssBgImages] = await Promise.all([
   580→    extractFonts($, url),
   581→    extractCssBgImages($, url),
   582→  ]);
   583→
   584→  const imgsDirect = extractImages(html, $, url);
   585→  const allImages = dedupeBy([...imgsDirect, ...cssBgImages], "src");
   586→
   587→  const { internal: internalLinks, external: externalLinks } = extractLinks(
   588→    $,
   589→    url
   590→  );
   591→  const files = extractFiles($, url);
   592→  const headings = extractHeadings($);
   593→  const productBlocks = extractProductBlocks($, url);
   594→
   595→  return {
   596→    meta: {
   597→      url,
   598→      title,
   599→      description,
   600→      scrapedAt: new Date().toISOString(),
   601→      mode: useApi ? "scraperapi" : "direct",
   602→    },
   603→    summary: {
   604→      images: allImages.length,
   605→      fonts: fonts.length,
   606→      files: files.length,
   607→      internalLinks: internalLinks.length,
   608→      externalLinks: externalLinks.length,
   609→      productBlocks: productBlocks.length,
   610→      headings: headings.length,
   611→    },
   612→    images: allImages,
   613→    fonts,
   614→    files,
   615→    links: { internal: internalLinks, external: externalLinks },
   616→    headings,
   617→    productBlocks,
   618→  };
   619→}
   620→
   621→/**
   622→ * Multi-page crawl: start at rootUrl, follow internal links that match
   623→ * pathFilter, up to maxPages pages.
   624→ *
   625→ * @param {string}   rootUrl    - Starting URL
   626→ * @param {RegExp}   pathFilter - Only follow links whose pathname matches
   627→ * @param {number}   maxPages   - Maximum pages to visit
   628→ * @param {boolean}  useApi
   629→ */
   630→export async function crawl(
   631→  rootUrl,
   632→  pathFilter = /.*/,
   633→  maxPages = 10,
   634→  useApi = false
   635→) {
   636→  const queue = [rootUrl];
   637→  const visited = new Set();
   638→  const results = [];
   639→
   640→  while (queue.length > 0 && visited.size < maxPages) {
   641→    const url = queue.shift();
   642→    if (visited.has(url)) continue;
   643→    visited.add(url);
   644→
   645→    console.log(`[crawl] Scraping (${visited.size}/${maxPages}): ${url}`);
   646→
   647→    try {
   648→      const data = await scrapeUrl(url, useApi);
   649→      results.push(data);
   650→
   651→      // Enqueue matching internal links not yet visited
   652→      for (const link of data.links.internal) {
   653→        if (!visited.has(link.href) && !queue.includes(link.href)) {
   654→          try {
   655→            const pathname = new URL(link.href).pathname;
   656→            if (pathFilter.test(pathname)) queue.push(link.href);
   657→          } catch {
   658→            // skip malformed
   659→          }
   660→        }
   661→      }
   662→    } catch (err) {
   663→      console.error(`[crawl] Failed ${url}: ${err.message}`);
   664→      results.push({ error: err.message, url });
   665→    }
   666→
   667→    // Polite delay between pages
   668→    if (queue.length > 0) await sleep(800);
   669→  }
   670→
   671→  return results;
   672→}
   673→
   674→function sleep(ms) {
   675→  return new Promise((r) => setTimeout(r, ms));
   676→}
   677→

