   131→      },
   132→      timeout: 30_000,
   133→      maxRedirects: 5,
   134→    });
   135→
   136→    const ct =
   137→      upstream.headers["content-type"] || "application/octet-stream";
   138→    const cl = upstream.headers["content-length"];
   139→    const name =
   140→      filename ||
   141→      decodeURIComponent(url.split("/").pop().split("?")[0]) ||
   142→      "download";
   143→
   144→    res.setHeader("Content-Type", ct);
   145→    res.setHeader(
   146→      "Content-Disposition",
   147→      `attachment; filename="${encodeURIComponent(name)}"`
   148→    );
   149→    if (cl) res.setHeader("Content-Length", cl);
   150→
   151→    upstream.data.pipe(res);
   152→  } catch (err) {
