   465→    external: dedupeBy(external, "href"),
   466→  };
   467→}
   468→
   469→// ---------------------------------------------------------------------------
   470→// Headings extraction
   471→// ---------------------------------------------------------------------------
   472→
   473→function extractHeadings($) {
   474→  const headings = [];
   475→  // Single combined selector preserves document order (not grouped by tag)
   476→  $("h1, h2, h3, h4").each((_, el) => {
   477→    const text = $(el).text().trim().replace(/\s+/g, " ");
   478→    if (text) headings.push({ level: el.name, text });
   479→  });
   480→  return headings;
   481→}
   482→
   483→// ---------------------------------------------------------------------------
   484→// Product / pricing block extraction
   485→// ---------------------------------------------------------------------------
   486→
   487→function extractProductBlocks($, baseUrl) {
   488→  const blocks = [];
   489→  const priceRe = /(?:AU\$|USD?\$|\$|€|£|¥)\s?\d[\d,]*(?:\.\d{2})?/gi;
   490→
   491→  // Check sections, articles, divs with class hints
   492→  const selectors = [
   493→    "section",
   494→    "article",
   495→    '[class*="product"]',
   496→    '[class*="card"]',
   497→    '[class*="price"]',
   498→    '[class*="item"]',
   499→  ];
   500→
   501→  const seen = new Set();
   502→
   503→  selectors.forEach((sel) => {
   504→    $(sel).each((_, el) => {
   505→      const text = $(el).text().trim().replace(/\s+/g, " ");
   506→      if (!text || seen.has(text.slice(0, 80))) return;
   507→
   508→      const priceMatches = text.match(priceRe);
   509→      if (!priceMatches) return;
   510→
   511→      seen.add(text.slice(0, 80));
   512→
   513→      // Grab any image inside the block
   514→      const imgEl = $(el).find("img[src]").first();
   515→      const imgSrc = imgEl.length
   516→        ? safeAbsolute(imgEl.attr("src"), baseUrl)
   517→        : null;
   518→
   519→      // Grab heading inside block
   520→      const heading = $(el).find("h1,h2,h3,h4,h5").first().text().trim();
   521→
   522→      blocks.push({
   523→        heading: heading || "",
   524→        prices: [...new Set(priceMatches)],
   525→        image: imgSrc,
   526→        snippet: text.slice(0, 400),
   527→      });
   528→    });
   529→  });
   530→
   531→  return blocks.slice(0, 30); // cap for demo
   532→}
   533→
   534→// ---------------------------------------------------------------------------
   535→// CSS background-image sweep — uses pre-fetched CSS blocks (no double-fetch)
   536→// ---------------------------------------------------------------------------
   537→
   538→function extractCssBgImagesFromCss(cssBlocks) {
   539→  const images = [];
   540→  for (const { css, base } of cssBlocks) {
   541→    for (const url of extractBgImages(css, base)) {
   542→      images.push({ src: url, alt: "", source: "css-background" });
   543→    }
   544→  }
   545→  return images;
   546→}
   547→
   548→// ---------------------------------------------------------------------------
   549→// Main entry point
   550→// ---------------------------------------------------------------------------
   551→
   552→/**
   553→ * Scrape a URL and return a structured result object.
   554→ *
   555→ * @param {string} url       - Target URL
   556→ * @param {boolean} useApi   - true = use ScraperAPI, false = direct fetch
   557→ * @returns {Promise<object>}
   558→ */
   559→export async function scrapeUrl(url, useApi = false) {
   560→  const html = useApi ? await fetchViaScraperApi(url) : await fetchDirect(url);
   561→
   562→  const $ = cheerio.load(html);
   563→  const title = $("title").text().trim().replace(/\s+/g, " ");
   564→  const description =
   565→    $('meta[name="description"]').attr("content") ||
   566→    $('meta[property="og:description"]').attr("content") ||
   567→    "";
   568→
   569→  // Fetch all stylesheets once, then extract fonts and CSS bg-images from them
   570→  const cssBlocks = await fetchAllCss($, url);
   571→  const fonts = extractFontsFromCss(cssBlocks);
   572→  const cssBgImages = extractCssBgImagesFromCss(cssBlocks);
   573→
   574→  const imgsDirect = extractImages(html, $, url);
   575→  const allImages = dedupeBy([...imgsDirect, ...cssBgImages], "src");
   576→
   577→  const { internal: internalLinks, external: externalLinks } = extractLinks(
   578→    $,
   579→    url
   580→  );
   581→  const files = extractFiles($, url);
   582→  const headings = extractHeadings($);
   583→  const productBlocks = extractProductBlocks($, url);
   584→
   585→  return {
   586→    meta: {
   587→      url,
   588→      title,
   589→      description,
   590→      scrapedAt: new Date().toISOString(),
   591→      mode: useApi ? "scraperapi" : "direct",
   592→    },
   593→    summary: {
   594→      images: allImages.length,
   595→      fonts: fonts.length,
   596→      files: files.length,
   597→      internalLinks: internalLinks.length,
   598→      externalLinks: externalLinks.length,
   599→      productBlocks: productBlocks.length,
   600→      headings: headings.length,
   601→    },
   602→    images: allImages,
   603→    fonts,
   604→    files,
   605→    links: { internal: internalLinks, external: externalLinks },
   606→    headings,
   607→    productBlocks,
   608→  };
   609→}
   610→
   611→/**
   612→ * Multi-page crawl: start at rootUrl, follow internal links that match
   613→ * pathFilter, up to maxPages pages.
   614→ *
   615→ * @param {string}   rootUrl    - Starting URL
   616→ * @param {RegExp}   pathFilter - Only follow links whose pathname matches
   617→ * @param {number}   maxPages   - Maximum pages to visit
   618→ * @param {boolean}  useApi
   619→ */
   620→export async function crawl(
   621→  rootUrl,
   622→  pathFilter = /.*/,
   623→  maxPages = 10,
   624→  useApi = false
   625→) {
   626→  const queue = [rootUrl];
   627→  const visited = new Set();
   628→  const queued = new Set([rootUrl]); // tracks what's already in the queue (O(1) lookup)
   629→  const results = [];
   630→
   631→  while (queue.length > 0 && visited.size < maxPages) {
   632→    const url = queue.shift();
   633→    if (visited.has(url)) continue;
   634→    visited.add(url);
   635→
   636→    console.log(`[crawl] Scraping (${visited.size}/${maxPages}): ${url}`);
   637→
   638→    try {
   639→      const data = await scrapeUrl(url, useApi);
   640→      results.push(data);
   641→
   642→      // Enqueue matching internal links not yet visited
   643→      for (const link of data.links.internal) {
   644→        if (!visited.has(link.href) && !queued.has(link.href)) {
   645→          try {
   646→            const pathname = new URL(link.href).pathname;
   647→            if (pathFilter.test(pathname)) {
   648→              queued.add(link.href);
   649→              queue.push(link.href);
   650→            }
   651→          } catch {
   652→            // skip malformed
   653→          }
   654→        }
   655→      }
   656→    } catch (err) {
   657→      console.error(`[crawl] Failed ${url}: ${err.message}`);
   658→      results.push({ error: err.message, url });
   659→    }
   660→
   661→    // Polite delay between pages
   662→    if (queue.length > 0) await sleep(800);
   663→  }
   664→
   665→  return results;
   666→}
   667→
   668→function sleep(ms) {
   669→  return new Promise((r) => setTimeout(r, ms));
   670→}
   671→

